// We know that when a black hole eats stuff, it grows.
//
// We also know that time slows down when you are near a black hole, 
// to the extreme that stuff falling into a black hole will appear to
// slow down and finally frozen at the event horizon.
// 
// But wait, if we cannot see anything fall into the black hole, how can
// we see it grow?
// 
// The answer is gravitational lensing, which makes the black hole appear
// to grow even before it eats the stuff.
//
// This simulation shows a spherical shell falling into the center black
// hole. The right half is what physically happens. The left part is what
// we see as an observer outside the black hole. Notice how the black hole
// grows as the outer shell shrinks.
//
// The following code is based on my previous black hole shader
// https://www.shadertoy.com/view/fdyXRR

#define GROW_FACTOR 1.2

#define PI 3.14159265359
#define N 800
#define dt 0.01

float sphereTexture(vec3 p) {
    p = p / length(p);
    float phi = atan(p.y, p.x);
    float theta = asin(p.z);
    return fract(phi / PI * 8.) < 0.11 / (0.1 + length(p.xy)) || fract(theta / PI * 8.) < 0.1 ? 0. : 1.;
}

vec4 trace_sphere(vec3 o, vec3 d, float r) {
    float b = 2. * dot(o, d);
    float c = dot(o, o) - r * r;
    float det = b * b - 4. * c;
    if (c <= 0. || det < 0.) {
        return vec4(0.);
    }
    float t = 0.5 * (-b - sqrt(det));
    return vec4(o + t * d, 1.);
}

void trace_blackhole(vec3 o, vec3 d, float R, out vec4 p1, out vec4 p2) {
    vec3 c = cross(o, d);
    float l = -1.5 * dot(c, c);
    vec3 x = o;
    float r = length(x);
    float r_ = r;
    vec3 a = l * pow(r, -5.) * x;
    vec3 x_ = x + d * dt + .5 * x * dt * dt;
    bool is_outside = true;
    for (int i = 0; i < N && r < 10.; ++i) {
        r_ = length(x_);
        if (is_outside && r_ <= R) {
            is_outside = false;
            p1 = vec4(mix(x, x_, (R - r) / (r_ - r)), 1.);
        }
        if (r_ <= 1.) {
            p2 = vec4(mix(x, x_, (1. - r) / (r_ - r)), 1.);
            return;
        }
        r = r_;
        a = l * (r > R ? GROW_FACTOR : 1.) * pow(r, -5.) * x_;
        vec3 tmp = x_;
        x_ = 2. * x_ - x + a * dt * dt;
        x = tmp;
    }
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy * 2. - 1.) * iResolution.xy / vec2(min(iResolution.x, iResolution.y)) * 2.;
    vec3 col = vec3(1);

    float t = iTime + .5;
    vec3 o = 5. * vec3(1., .2, .7);
    vec3 z = normalize(o);
    vec3 x = normalize(cross(vec3(0., .5, 1.), z));
    vec3 y = cross(z, x);
    float R = max(1., .9 + (1. - sin(iTime*.5)) * 2.3);

    vec4 p1, p2;
    vec3 d;
    if (abs(uv.x) < 0.01) {
        col *= .2;
    }
    if (uv.x > 0.) {
        uv.x -= 1.5;
        d = normalize(3. * (x * uv.x + y * uv.y) - o);
        p1 = trace_sphere(o, d, R);
        p2 = trace_sphere(o, d, 1.);
    } else {
        uv.x += 1.5;
        d = normalize(3. * (x * uv.x + y * uv.y) - o);
        trace_blackhole(o, d, R, p1, p2);
    }
    if (p1.w > 0.) {
        col *= 0.2 + sphereTexture(p1.xyz) * 0.7;
    }
    if (p2.w > 0.) {
        col *= 0.2 + sphereTexture(p2.xyz) * 0.7;
        col *= 0.5;
    }
    fragColor = vec4(col, 1.0);
}
